import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
L = list(L)
# generate all possible triples (a,b,c) with a<b and a+b=c
triples = []
for a, b in itertools.combinations(L, 2):
    c = a + b
    if c in L and c != a and c != b:
        triples.append((a, b, c))
# backtracking exact cover
used = set()
solution = []

def backtrack(start):
    if len(solution) == 15:
        return True
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack(i + 1):
            return True
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)
if found:
    witness = {"polarity": "positive", "data": {"triples": solution}}
else:
    witness = {"polarity": "negative", "basis": "search", "search_exhausted": True, "nodes_explored": None, "method": "backtrack"}
print("WITNESS: " + json.dumps(witness))
